// Package java261 holds the Java 26.1 (protocol 775) lookup tables. The data under data/ is
// generated by tools/gentables from minecraft-data; nothing here is written by hand.
package java261

import (
	"bytes"
	"compress/gzip"
	"embed"
	"io"
	"log"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/df-mc/dragonfly/server/world"
)

// ProtocolVersion is the Java protocol number these tables describe.
const ProtocolVersion = 775

//go:embed data/*.gz
var dataFS embed.FS

// lines returns the data lines of one embedded table, without comments.
func lines(name string) []string {
	f, err := dataFS.Open("data/" + name + ".gz")
	if err != nil {
		panic(err)
	}
	defer f.Close()
	zr, err := gzip.NewReader(f)
	if err != nil {
		panic(err)
	}
	raw, err := io.ReadAll(zr)
	if err != nil {
		panic(err)
	}
	var out []string
	for _, l := range strings.Split(string(bytes.TrimSpace(raw)), "\n") {
		if l != "" && l[0] != '#' {
			out = append(out, l)
		}
	}
	return out
}

// fields splits a table line at tabs.
func fields(l string) []string { return strings.Split(l, "\t") }

func atoi(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		panic(err)
	}
	return n
}

// --- blocks ---

var (
	stateMu    sync.Mutex
	stateTable atomic.Pointer[[]uint16] // nil until built; afterwards lookups are one load and one slice read
)

// registryReady reports whether the registry has been finalized. Dragonfly's registry panics
// when asked for its size before that, so the question is asked by trying.
func registryReady(reg interface{ BlockCount() int }) (ok bool) {
	defer func() {
		if recover() != nil {
			ok = false
		}
	}()
	reg.BlockCount()
	return true
}

// JavaState returns the Java block state ID for a Bedrock runtime ID, as Dragonfly's default
// block registry numbers it. It does not finalize the registry: every block type must be
// registered and the registry finalized before the first call, which panics with a clear
// message otherwise. The table is built on that first call.
//
// A state with no exact mapping uses the nearest mapped state of the same block, or that
// block's default state; only a block Java does not have shows as stone. Runtime IDs past the
// end of the registry give air.
func JavaState(bedrockRuntimeID uint32) uint16 {
	t := stateTable.Load()
	if t == nil {
		t = buildStateTable()
	}
	if int(bedrockRuntimeID) >= len(*t) {
		return (*t)[0] // unreachable for valid chunks; never panic on the send path
	}
	return (*t)[bedrockRuntimeID]
}

// buildStateTable checks the registry and builds the table once. Until the registry is
// finalized it panics on every call, and nothing is cached.
func buildStateTable() *[]uint16 {
	stateMu.Lock()
	defer stateMu.Unlock()
	if t := stateTable.Load(); t != nil {
		return t
	}
	reg := world.DefaultBlockRegistry
	if !registryReady(reg) {
		panic("java261: JavaState called before the block registry was finalized; register every block and finalize the registry first")
	}
	table, st, _ := buildStates(reg.BlockCount(), reg.RuntimeIDToState, log.Printf)
	log.Printf("java261: %d block states: %d exact, %d nearest or default, %d stone", len(table), st.Exact, st.Fallback, st.Stone)
	stateTable.Store(&table)
	return &table
}

// stoneKey is the mapping key of the fallback block.
const stoneKey = "minecraft:stone[]"

// Stats says how each block state was resolved.
type Stats struct {
	Exact    int // the mapping has this state, with every property it carries
	Fallback int // the block exists in Java; a nearest or default state, or a state that ignored properties the mapping lacks
	Stone    int // no Java block of that name; stone is used
}

// How one state was resolved, per runtime ID.
const (
	kindExact byte = iota
	kindFallback
	kindStone
)

// blockRange is the state ID range and default state of one Java block.
type blockRange struct{ min, max, def uint16 }

// buildStates maps runtime IDs 0..n-1 to Java state IDs. An exact mapping wins. Otherwise, if
// the block name is in the mapping, the mapped state sharing the most property values, unless
// that is no property at all or several Java blocks tie, in which case the Java block of the
// same name gives its default state; else a block Java has under another name gives its default
// state; else stone. logf gets one line per block name that needed a fallback. The maps live
// only for this call. The kinds say how each state was resolved.
func buildStates(n int, state func(uint32) (string, map[string]any, bool), logf func(string, ...any)) ([]uint16, Stats, []byte) {
	type entry struct {
		props []string // "k=v" pairs
		id    uint16
	}
	m := make(map[string]uint16, 12000)
	known := map[string]map[string]bool{} // block name -> property names the mapping uses
	byName := map[string][]entry{}
	for _, l := range lines("blocks") {
		f := fields(l)
		id := uint16(atoi(f[1]))
		m[f[0]] = id
		name, props, _ := strings.Cut(strings.TrimSuffix(f[0], "]"), "[")
		if known[name] == nil {
			known[name] = map[string]bool{}
		}
		var pairs []string
		if props != "" {
			pairs = strings.Split(props, ",")
		}
		for _, kv := range pairs {
			k, _, _ := strings.Cut(kv, "=")
			known[name][k] = true
		}
		byName[name] = append(byName[name], entry{pairs, id})
	}
	var ranges []blockRange
	defaults := map[string]uint16{} // Java block name -> default state
	for _, l := range lines("defaults") {
		f := fields(l)
		ranges = append(ranges, blockRange{uint16(atoi(f[1])), uint16(atoi(f[2])), uint16(atoi(f[3]))})
		defaults[f[0]] = uint16(atoi(f[3]))
	}
	sort.Slice(ranges, func(i, j int) bool { return ranges[i].min < ranges[j].min })
	blockOf := func(id uint16) blockRange {
		return ranges[sort.Search(len(ranges), func(i int) bool { return ranges[i].max >= id })]
	}
	stone := m[stoneKey]
	out := make([]uint16, n)
	kinds := make([]byte, n)
	logged := map[string]bool{}
	var st Stats
	note := func(name, how string) {
		if !logged[name] {
			logged[name] = true
			logf("java261: %s: %s", name, how)
		}
	}
	for i := range out {
		name, props, ok := state(uint32(i))
		if !ok {
			out[i], kinds[i] = stone, kindStone
			st.Stone++
			note(name, "unknown runtime ID, using stone")
			continue
		}
		key := stateKey(name, props, known[name])
		if v, found := m[key]; found {
			v, n := withNewerProperties(v, props)
			out[i] = v
			if strings.Count(key, "=")+n == len(props) {
				st.Exact++
				continue
			}
			kinds[i] = kindFallback
			st.Fallback++
			note(name, "properties the mapping does not know were ignored")
			continue
		}
		kinds[i] = kindFallback
		if cands := byName[name]; len(cands) > 0 {
			have := map[string]bool{}
			_, kv, _ := strings.Cut(strings.TrimSuffix(key, "]"), "[")
			for _, p := range strings.Split(kv, ",") {
				have[p] = true
			}
			var best []entry
			bestScore := -1
			for _, c := range cands {
				score := 0
				for _, p := range c.props {
					if have[p] {
						score++
					}
				}
				if score > bestScore {
					best, bestScore = best[:0], score
				}
				if score == bestScore {
					best = append(best, c)
				}
			}
			first := blockOf(best[0].id)
			oneBlock := true
			for _, c := range best {
				if blockOf(c.id) != first {
					oneBlock = false
				}
			}
			switch d, same := defaults[name]; {
			case bestScore > 0 && oneBlock:
				out[i] = best[0].id
				note(name, "some states have no mapping, using the nearest state")
			case same:
				out[i] = d
				note(name, "no close mapping, using the Java default state")
			case oneBlock:
				out[i] = first.def
				note(name, "no close mapping, using the default state of the mapped Java block")
			default:
				out[i] = best[0].id
				note(name, "no close mapping, using the first mapped state")
			}
		} else if d, found := defaults[name]; found {
			out[i] = d
			note(name, "no mapping, using the Java default state")
		} else {
			out[i], kinds[i] = stone, kindStone
			note(name, "no Java block of that name, using stone")
		}
		if kinds[i] == kindStone {
			st.Stone++
		} else {
			st.Fallback++
		}
	}
	return out, st, kinds
}

// newerProperties are Bedrock properties newer than the pinned mapping
// (bedrock 1.26.30), which Dragonfly 0.11.6 (1.26.60) stores and works out on
// the server: the connections of fences, panes, bars, fire and chorus plants,
// and the sides of redstone wire. Each is the Java property of the same
// meaning; a bool becomes "true" or "false", and a wire side keeps its word
// (none, side, up), which is Java's too (minecraft-data's pc blocks.json).
var newerProperties = map[string]string{
	"minecraft:connection_north": "north",
	"minecraft:connection_east":  "east",
	"minecraft:connection_south": "south",
	"minecraft:connection_west":  "west",
	"minecraft:connection_up":    "up",
	"minecraft:connection_down":  "down",
	"redstone_north":             "north",
	"redstone_east":              "east",
	"redstone_south":             "south",
	"redstone_west":              "west",
}

// withNewerProperties sets on a Java state the Java properties of the Bedrock
// properties in newerProperties, and returns how many it set.
func withNewerProperties(state uint16, props map[string]any) (uint16, int) {
	n := 0
	for k, v := range props {
		java, ok := newerProperties[k]
		if !ok {
			continue
		}
		var val string
		switch x := v.(type) {
		case bool:
			val = strconv.FormatBool(x)
		case uint8:
			val = strconv.FormatBool(x != 0)
		case string:
			val = x
		default:
			continue
		}
		if s, ok := WithProperty(state, java, val); ok {
			state = s
			n++
		}
	}
	return state, n
}

// stateKey renders a block the way the mapping data writes it: properties sorted by name,
// booleans as 0 or 1. If keep is not nil, properties outside it are left out: Dragonfly's
// palette can carry newer properties than the mapping data knows.
func stateKey(name string, props map[string]any, keep map[string]bool) string {
	names := make([]string, 0, len(props))
	for k := range props {
		if keep == nil || keep[k] {
			names = append(names, k)
		}
	}
	sort.Strings(names)
	var b strings.Builder
	b.WriteString(name)
	b.WriteByte('[')
	for i, k := range names {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(k)
		b.WriteByte('=')
		switch v := props[k].(type) {
		case bool:
			if v {
				b.WriteByte('1')
			} else {
				b.WriteByte('0')
			}
		case string:
			b.WriteString(v)
		default:
			b.WriteString(anyInt(v))
		}
	}
	b.WriteByte(']')
	return b.String()
}

func anyInt(v any) string {
	switch n := v.(type) {
	case uint8:
		return strconv.Itoa(int(n))
	case int32:
		return strconv.Itoa(int(n))
	case int:
		return strconv.Itoa(n)
	case int64:
		return strconv.FormatInt(n, 10)
	case int16:
		return strconv.Itoa(int(n))
	case uint32:
		return strconv.FormatUint(uint64(n), 10)
	}
	panic("java261: unsupported block property type")
}

// --- items ---

var (
	itemOnce   sync.Once
	itemToJava map[string]int32 // "name", "name#meta", "name#*" (any meta) or "name#+" (any non-zero meta)
	javaToItem []bedrockItem    // by Java item ID
)

type bedrockItem struct {
	name string // empty if the Java item has no Bedrock counterpart
	meta int16
}

func loadItems() {
	itemOnce.Do(func() {
		ls := lines("items")
		itemToJava = make(map[string]int32, len(ls))
		for _, l := range ls {
			f := fields(l)
			id := int32(atoi(f[1]))
			itemToJava[f[0]] = id
			if len(f) < 3 { // not the chosen reverse name
				continue
			}
			for int(id) >= len(javaToItem) {
				javaToItem = append(javaToItem, bedrockItem{})
			}
			name, meta, _ := strings.Cut(f[0], "#")
			javaToItem[id] = bedrockItem{name, int16(atoi0(meta))}
		}
	})
}

// atoi0 is atoi with "" as 0.
func atoi0(s string) int {
	if s == "" {
		return 0
	}
	return atoi(s)
}

const prefix = "minecraft:"

// JavaItem maps a Bedrock item name and meta to its Java item ID. Beds and banners carry their
// colour as meta and map to the Java item of that colour. Potions, splash and lingering potions,
// goat horns, suspicious stew and firework stars carry their variant as meta, which Java holds
// as item components on one item, so any meta gives that item (the caller sends the variant as a
// component). An arrow with meta is a tipped arrow. Any other name with a non-zero meta, or a
// colour out of range, is not mapped (ok is false).
func JavaItem(bedrockName string, meta int16) (id int32, ok bool) {
	loadItems()
	name := strings.TrimPrefix(bedrockName, prefix)
	tries := []string{name + "#" + strconv.Itoa(int(meta)), name + "#+", name + "#*"}
	if meta == 0 {
		tries = []string{name + "#0", name, name + "#*"}
	}
	for _, k := range tries {
		if id, ok = itemToJava[k]; ok {
			return id, true
		}
	}
	return 0, false
}

// BedrockItem is the reverse of JavaItem. The name carries the minecraft: prefix. Where several
// Bedrock names map to one Java item, it gives the one named like the Java item; lit and double
// slab variants are never returned.
func BedrockItem(javaID int32) (name string, meta int16, ok bool) {
	loadItems()
	if javaID < 0 || int(javaID) >= len(javaToItem) || javaToItem[javaID].name == "" {
		return "", 0, false
	}
	it := javaToItem[javaID]
	return prefix + it.name, it.meta, true
}

// --- biomes ---

var (
	biomeOnce sync.Once
	biomes    map[string]int32
)

// JavaBiome returns the Java biome ID of a biome name, with or without the minecraft:
// prefix, or -1 if the name is unknown.
func JavaBiome(name string) int32 {
	biomeOnce.Do(func() {
		ls := lines("biomes")
		biomes = make(map[string]int32, len(ls))
		for _, l := range ls {
			f := fields(l)
			biomes[f[0]] = int32(atoi(f[1]))
		}
	})
	if id, ok := biomes[strings.TrimPrefix(name, prefix)]; ok {
		return id
	}
	return -1
}

// --- packets ---

var (
	packetOnce sync.Once
	packets    map[string]int32
)

// PacketID returns the packet ID for a protocol state (handshaking, status, login,
// configuration, play), a direction (toClient, toServer) and the packet's name in
// minecraft-data, or -1 if there is no such packet.
func PacketID(state, direction, name string) int32 {
	packetOnce.Do(func() {
		ls := lines("packets")
		packets = make(map[string]int32, len(ls))
		for _, l := range ls {
			f := fields(l)
			packets[f[0]+"/"+f[1]+"/"+f[2]] = int32(atoi(f[3]))
		}
	})
	if id, ok := packets[state+"/"+direction+"/"+name]; ok {
		return id
	}
	return -1
}

// PacketName returns the minecraft-data name of a packet ID, or "" when that
// state and direction have no such packet.
func PacketName(state, direction string, id int32) string {
	PacketID(state, direction, "") // make sure the table is loaded
	prefix := state + "/" + direction + "/"
	for k, v := range packets {
		if v == id && strings.HasPrefix(k, prefix) {
			return k[len(prefix):]
		}
	}
	return ""
}

// --- entities ---

var (
	entityOnce sync.Once
	entities   map[string]int32
)

// EntityType returns the Java entity type ID of a name, with or without the
// minecraft: prefix, or -1 when unknown.
func EntityType(name string) int32 {
	entityOnce.Do(func() {
		ls := lines("entities")
		entities = make(map[string]int32, len(ls))
		for _, l := range ls {
			f := fields(l)
			entities[f[0]] = int32(atoi(f[1]))
		}
	})
	if id, ok := entities[strings.TrimPrefix(name, prefix)]; ok {
		return id
	}
	return -1
}

// --- registries ---

// Registry is one registry the server sends during configuration, with its entry keys in
// network order.
type Registry struct {
	ID      string
	Entries []string
}

// Registries returns the registries in the order the login packet lists them. The result is
// built on each call and not kept, because it is only needed once per login.
func Registries() []Registry {
	var out []Registry
	for _, l := range lines("registries") {
		f := fields(l)
		out = append(out, Registry{ID: f[0], Entries: f[1:]})
	}
	return out
}
